{"content":"import { promises as fs } from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

const dataFile = path.join(process.cwd(), 'books.json');

/**
 * @typedef {Object} Book
 * @property {string} id
 * @property {string} title
 * @property {string} author
 * @property {string} notes
 * @property {boolean} finished
 * @property {string} addedAt
 */

async function ensureFile() {
  try {
    await fs.access(dataFile);
  } catch {
    await fs.writeFile(dataFile, '[]', 'utf8');
  }
}

/** @returns {Promise<Book[]>} */
export async function readBooks() {
  await ensureFile();
  const raw = await fs.readFile(dataFile, 'utf8');
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/** @param {Book[]} books */
async function writeBooks(books) {
  await fs.writeFile(dataFile, JSON.stringify(books, null, 2), 'utf8');
}

/** @returns {Promise<Book[]>} sorted: unfinished first, then by newest added */
export async function getBooks() {
  const books = await readBooks();
  return books.sort((a, b) => {
    if (a.finished !== b.finished) return a.finished ? 1 : -1;
    return b.addedAt.localeCompare(a.addedAt);
  });
}

/** @param {string} id */
export async function getBook(id) {
  const books = await readBooks();
  return books.find((b) => b.id === id) || null;
}

/**
 * @param {{title: string, author: string, notes?: string}} input
 * @returns {Promise<Book>}
 */
export async function addBook({ title, author, notes }) {
  const books = await readBooks();
  /** @type {Book} */
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes || '').trim(),
    finished: false,
    addedAt: new Date().toISOString(),
  };
  books.push(book);
  await writeBooks(books);
  return book;
}

/** @param {string} id */
export async function markFinished(id) {
  const books = await readBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.finished = true;
  book.finishedAt = new Date().toISOString();
  await writeBooks(books);
  return book;
}
