{"content":":root {
  --bg: #faf8f5;
  --card: #ffffff;
  --ink: #1f1b16;
  --muted: #7a7268;
  --line: #e7e1d8;
  --accent: #8a5a2b;
  --accent-soft: #f3ece1;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.55;
}

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

.shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 0 20px 64px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28px 0 20px;
  border-bottom: 1px solid var(--line);
}

.brand {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--ink);
}

.add-link {
  font-weight: 600;
}

.content { padding-top: 28px; }

h1 { font-size: 1.5rem; margin: 0 0 4px; }
h2 { font-size: 1.1rem; margin: 28px 0 12px; color: var(--ink); }

.section { margin-bottom: 8px; }

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 16px 18px;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.card-title { font-weight: 600; }
.card-author { color: var(--muted); font-size: 0.95rem; }

.actions { display: flex; gap: 8px; flex-shrink: 0; }

button, .btn {
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--ink);
  border-radius: 8px;
  padding: 7px 14px;
  font-size: 0.9rem;
  cursor: pointer;
  font-family: inherit;
}
button:hover { border-color: var(--accent); }

.btn-primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.btn-primary:hover { opacity: 0.92; }

.btn-soft {
  background: var(--accent-soft);
  border-color: var(--accent-soft);
  color: var(--accent);
}

.tag {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 2px 10px;
}
.tag-done { color: #4a6b3a; border-color: #d4e3c8; background: #f1f6ec; }

form { max-width: 460px; }
label { display: block; font-weight: 600; margin: 18px 0 6px; font-size: 0.95rem; }
input, textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  background: var(--card);
  color: var(--ink);
}
textarea { min-height: 120px; resize: vertical; }
input:focus, textarea:focus { outline: none; border-color: var(--accent); }

.form-actions { margin-top: 22px; display: flex; gap: 10px; }

.empty { color: var(--muted); padding: 8px 0; }

.detail blockquote {
  white-space: pre-wrap;
  background: var(--accent-soft);
  border-left: 3px solid var(--accent);
  border-radius: 0 8px 8px 0;
  padding: 14px 16px;
  margin: 8px 0 0;
}
.detail .meta { color: var(--muted); font-size: 0.9rem; margin-top: 6px; }
.back-link { margin-bottom: 18px; display: inline-block; }
