import { useState } from 'react';
import { useRouter } from 'next/navigation';

export default function AddBookPage() {
  const router = useRouter();
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [notes, setNotes] = useState('');
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setError('');
    if (!title.trim() || !author.trim()) {
      setError('Title and author are required.');
      return;
    }
    setSaving(true);
    const res = await fetch('/api/books', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title, author, notes }),
    });
    setSaving(false);
    if (!res.ok) {
      setError('Could not save the book. Please try again.');
      return;
    }
    const book = await res.json();
    router.push(`/books/${book.id}`);
    router.refresh();
  }

  return (
    <div>
      <a href="/" className="back-link">&larr; Back</a>
      <h1>Add a Book</h1>

      <form onSubmit={handleSubmit}>
        <label htmlFor="title">Title</label>
        <input
          id="title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="The Hobbit"
          autoFocus
        />

        <label htmlFor="author">Author</label>
        <input
          id="author"
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          placeholder="J.R.R. Tolkien"
        />

        <label htmlFor="notes">Notes</label>
        <textarea
          id="notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Thoughts, quotes, why you picked it up..."
        />

        {error ? <p style={{ color: '#a23b1f', marginTop: 12 }}>{error}</p> : null}

        <div className="form-actions">
          <button type="submit" className="btn-primary" disabled={saving}>
            {saving ? 'Saving...' : 'Save book'}
          </button>
          <a href="/" className="btn" style={{ display: 'inline-flex', alignItems: 'center' }}>Cancel</a>
        </div>
      </form>
    </div>
  );
}
