{"content":"import { markFinished } from '../../../../../lib/books';
import { NextResponse } from 'next/server';

// Handles the "Mark finished" form submit. Accepts JSON (fetch) or form POST.
export async function POST(request, { params }) {
  const { id } = await params;
  const book = await markFinished(id);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }

  // If the client expects JSON (fetch), return the book; otherwise redirect.
  const accept = request.headers.get('accept') || '';
  if (accept.includes('application/json')) {
    return NextResponse.json(book);
  }
  return NextResponse.redirect(new URL(`/books/${id}`, request.url));
}
